package devs.time;
import static org.junit.jupiter.api.Assertions.*; import devs.iso.time.DecimalSimTime; import java.math.BigDecimal; import java.util.*; import org.junit.jupiter.api.Test;
class TimingErrorBudgetTest { @Test void observesDecimalErrors(){ var observed=new ArrayList<TimingErrorBudget.Observation>(); var budget=new TimingErrorBudget(new BigDecimal(".0001"),(a,b)->b.value().subtract(a.value()),observed::add,x->{}); budget.observe(new InteractionKey("a","o","b","i"),DecimalSimTime.of(new BigDecimal(".001")),DecimalSimTime.of(new BigDecimal(".002"))); assertEquals(new BigDecimal(".001"),observed.getFirst().error()); } }
